  let L = parseFloat(m[1]);
  if (m[1].indexOf('%') > -1) L /= 100;
  else if (L > 1) L /= 100;
  const C = parseFloat(m[2]), H = parseFloat(m[3]) * Math.PI / 180;
  const a = C * Math.cos(H), b = C * Math.sin(H);
